'use strict';
const KEY='portfolio-school-deadlines-v1';
const definitions=[{name:'Overdue',hint:'Deadline passed',ink:'#b13746',tint:'#ffedf0'},{name:'Urgent',hint:'Today – 2 days',ink:'#a55319',tint:'#fff0e2'},{name:'Soon',hint:'3 – 7 days',ink:'#916d0d',tint:'#fff7d9'},{name:'Upcoming',hint:'8 – 14 days',ink:'#3557b1',tint:'#edf1ff'},{name:'Later',hint:'More than 14 days',ink:'#617087',tint:'#edf0f5'}];
const el=id=>document.getElementById(id);
let tasks=[];
function validDate(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(value+'T12:00:00');return !isNaN(d)&&d.getFullYear()===Number(value.slice(0,4))&&d.getMonth()+1===Number(value.slice(5,7))&&d.getDate()===Number(value.slice(8,10));}
try{const saved=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(saved))throw Error();tasks=saved.filter(t=>typeof t.id==='string'&&typeof t.title==='string'&&typeof t.course==='string'&&typeof t.done==='boolean'&&validDate(t.due));}catch{el('notice').textContent='Saved deadlines could not be read. You can still add deadlines here.';}
function daysLeft(due,now=new Date()){return Math.round((Date.UTC(Number(due.slice(0,4)),Number(due.slice(5,7))-1,Number(due.slice(8,10)))-Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()))/86400000);}
function bucket(days){return days<0?0:days<=2?1:days<=7?2:days<=14?3:4;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(tasks));el('notice').textContent='';}catch{el('notice').textContent='This browser could not save your changes. Keep this page open to retain them.';}render();}
function addDeadline(data){const title=String(data.title||'').trim(),course=String(data.course||'').trim(),due=data.due;if(!title||title.length>150||course.length>80||!validDate(due))throw Error('Enter a title and a valid due date.');const task={id:crypto.randomUUID(),title,course,due,done:false};tasks.push(task);save();return task;}
function node(tag,text,className){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;}
function row(t){const d=daysLeft(t.due),def=definitions[bucket(d)],r=node('div',undefined,'row'+(t.done?' done':''));r.style.setProperty('--ink',def.ink);const check=node('input');check.type='checkbox';check.className='check';check.checked=t.done;check.setAttribute('aria-label',(t.done?'Mark incomplete: ':'Complete: ')+t.title);check.addEventListener('change',()=>{t.done=check.checked;if(t.examId)window.setExamDone(t.examId,t.done);else save();if(t.done)window.celebrate?.("assignment");});const detail=node('div',undefined,'task');detail.append(node('strong',t.title));if(t.course||t.examId)detail.append(node('small',[t.course,t.examId?'Exam':''].filter(Boolean).join(' · ')));const date=node('div',undefined,'date');date.append(node('span',t.done?'Completed':d<0?Math.abs(d)+' day'+(d===-1?'':'s')+' overdue':d===0?'Due today':d===1?'Due tomorrow':'In '+d+' days'));const time=node('time',new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(new Date(t.due+'T12:00:00')));time.dateTime=t.due;date.append(time);const remove=node('button','×','delete');remove.type='button';remove.setAttribute('aria-label','Delete '+t.title);remove.addEventListener('click',()=>{if(t.examId)window.deleteExam(t.examId);else{tasks=tasks.filter(item=>item.id!==t.id);save();}});r.append(check,detail,date,remove);return r;}
function render(){el('today').textContent=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'short',day:'numeric'}).format(new Date());const allTasks=[...tasks,...(window.getExamDeadlines?.()||[])];const pending=allTasks.filter(t=>!t.done).sort((a,b)=>a.due.localeCompare(b.due)),done=allTasks.filter(t=>t.done).sort((a,b)=>a.due.localeCompare(b.due));el('count').textContent=pending.length;el('groups').replaceChildren();if(!pending.length){const empty=node('div',undefined,'empty');empty.append(node('strong',allTasks.length?'All caught up.':'Make room for what’s next.'),node('p',allTasks.length?'Your completed deadlines are below.':'Add your first assignment or exam above.'));el('groups').append(empty);}definitions.forEach((def,i)=>{const items=pending.filter(t=>bucket(daysLeft(t.due))===i);if(!items.length)return;const section=node('section',undefined,'group');section.style.setProperty('--ink',def.ink);section.style.setProperty('--tint',def.tint);const heading=node('div',undefined,'group-title');heading.append(node('h3',def.name+' · '+items.length,'badge'),node('p',def.hint));const rows=node('div',undefined,'rows');items.forEach(t=>rows.append(row(t)));section.append(heading,rows);el('groups').append(section);});el('completed').hidden=!done.length;el('completed-count').textContent=done.length;el('completed-list').className='rows';el('completed-list').replaceChildren(...done.map(row));}
el('deadline-form').addEventListener('submit',event=>{event.preventDefault();try{addDeadline(Object.fromEntries(new FormData(event.currentTarget)));event.currentTarget.reset();el('title').focus();}catch(error){el('notice').textContent=error.message;}});
render();setInterval(render,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});window.addEventListener('storage',event=>{if(event.key===KEY){try{const saved=JSON.parse(event.newValue||'[]');if(Array.isArray(saved)&&saved.every(t=>typeof t.id==='string'&&typeof t.title==='string'&&typeof t.course==='string'&&typeof t.done==='boolean'&&validDate(t.due))){tasks=saved;render();}}catch{}}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'list_deadlines',description:'Read school deadlines with their current urgency.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>tasks.map(t=>({...t,urgency:t.done?'Completed':definitions[bucket(daysLeft(t.due))].name}))},{name:'add_deadline',description:'Add an assignment or exam to this browser’s school deadline list.',inputSchema:{type:'object',properties:{title:{type:'string',maxLength:150},course:{type:'string',maxLength:80},due:{type:'string',format:'date'}},required:['title','due'],additionalProperties:false},annotations:{readOnlyHint:false},execute:addDeadline}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}


